   187	def markdown_to_html(markdown: str) -> str:
   188	    lines = markdown.strip().splitlines()
   189	    out: list[str] = []
   190	    para: list[str] = []
   191	    in_list = False
   192	
   193	    def flush_para() -> None:
   194	        nonlocal para
   195	        if para:
   196	            out.append(f"<p>{render_inline(' '.join(para).strip())}</p>")
   197	            para = []
   198	
   199	    def close_list() -> None:
   200	        nonlocal in_list
   201	        if in_list:
   202	            out.append("</ul>")
   203	            in_list = False
   204	
   205	    for raw_line in lines:
   206	        line = raw_line.rstrip()
   207	        stripped = line.strip()
   208	
   209	        if not stripped:
   210	            flush_para()
   211	            close_list()
   212	            continue
   213	
   214	        if stripped.startswith("## "):
   215	            flush_para()
   216	            close_list()
   217	            out.append(f"<h2>{render_inline(stripped[3:].strip())}</h2>")
   218	            continue
   219	
   220	        if stripped.startswith("- "):
   221	            flush_para()
   222	            if not in_list:
   223	                out.append("<ul>")
   224	                in_list = True
   225	            out.append(f"<li>{render_inline(stripped[2:].strip())}</li>")
   226	            continue
   227	
   228	        close_list()
   229	        para.append(stripped)
   230	
   231	    flush_para()
   232	    close_list()
   233	    return "\n".join(out)
