   236	def load_jobs(today: date) -> list[Job]:
   237	    jobs: list[Job] = []
   238	    for path in sorted(SOURCE_DIR.glob("*.md")):
   239	        if path.name in SKIP_FILES:
   240	            continue
   241	        raw = path.read_text(encoding="utf-8")
   242	        meta, body = parse_front_matter(raw, path)
   243	
   244	        missing = [field for field in REQUIRED_FIELDS if not clean_text(meta.get(field))]
   245	        if missing:
   246	            raise ValueError(f"{path}: thiếu field bắt buộc {missing}")
   247	
   248	        publish_date = parse_date(clean_text(meta["publishDate"]), "publishDate", path)
   249	        deadline = parse_date(clean_text(meta["deadline"]), "deadline", path)
   250	        href = f"tuyen-dung/{clean_text(meta['slug'])}.html"
   251	        detail_path = OUTPUT_DIR / f"{clean_text(meta['slug'])}.html"
   252	        effective_status = infer_effective_status(meta, deadline, today)
   253	
   254	        meta = dict(meta)
   255	        meta["status"] = effective_status
   256	        meta["publishDate"] = publish_date.isoformat()
   257	        meta["deadline"] = deadline.isoformat()
   258	        meta["href"] = href
   259	        meta["salaryLabel"] = clean_text(meta.get("salaryLabel"))
   260	        meta["location"] = clean_text(meta.get("location"))
   261	        meta["summary"] = clean_text(meta.get("summary"))
   262	        meta["companyName"] = clean_text(meta.get("companyName"))
   263	        meta["title"] = clean_text(meta.get("title"))
   264	        meta["workMode"] = clean_text(meta.get("workMode"))
   265	        meta["employmentType"] = clean_text(meta.get("employmentType"))
   266	        meta["experienceLevel"] = clean_text(meta.get("experienceLevel"))
   267	        meta["featured"] = bool(meta.get("featured"))
   268	        meta["urgent"] = bool(meta.get("urgent"))
   269	        meta["tags"] = meta.get("tags") or []
   270	        location_key, location_label = infer_location_group(meta["location"], meta["tags"])
   271	        meta["locationGroupKey"] = location_key
   272	        meta["locationGroupLabel"] = location_label
   273	        role_key, role_label = infer_role_group(meta["title"], meta["tags"])
   274	        meta["roleGroupKey"] = role_key
   275	        meta["roleGroupLabel"] = role_label
   276	
   277	        jobs.append(
   278	            Job(
   279	                meta=meta,
   280	                body_markdown=body,
   281	                body_html=markdown_to_html(body),
   282	                href=href,
   283	                detail_path=detail_path,
   284	                publish_date=publish_date,
   285	                deadline=deadline,
   286	                effective_status=effective_status,
   287	            )
   288	        )
   289	    return jobs
