   385	
   386	      function initJobsFilter() {
   387	        var form = document.getElementById('jobsFilterForm');
   388	        var grid = document.getElementById('jobsListGrid');
   389	        if (!form || !grid) return;
   390	
   391	        var cards = Array.prototype.slice.call(grid.querySelectorAll('.job-card'));
   392	        var resultCount = document.getElementById('jobsFilterCount');
   393	        var emptyState = document.getElementById('jobsEmptyState');
   394	        var searchInput = document.getElementById('jobsFilterSearch');
   395	        var locationSelect = document.getElementById('jobsFilterLocation');
   396	        var roleSelect = document.getElementById('jobsFilterRole');
