   402	        var activeFilters = document.getElementById('jobsActiveFilters');
   403	        var quickRoleButtons = Array.prototype.slice.call(document.querySelectorAll('.jobs-quick-chip[data-role-value]'));
   404	
   405	        function getSelectedLabel(select) {
   406	          if (!select || !select.options || select.selectedIndex < 0) return '';
   407	          return select.options[select.selectedIndex].textContent || '';
   408	        }
   409	
   410	        function syncQuickRoleButtons() {
   411	          var selectedRole = roleSelect ? roleSelect.value : '';
   412	          quickRoleButtons.forEach(function (button) {
   413	            button.classList.toggle('is-active', (button.dataset.roleValue || '') === selectedRole);
   414	          });
   415	        }
   416	
   417	        function renderActiveFilters(filters) {
   418	          if (!activeFilters) return;
   419	          if (!filters.length) {
   420	            activeFilters.hidden = true;
   421	            activeFilters.innerHTML = '';
   422	            return;
   423	          }
   424	
   425	          activeFilters.hidden = false;
   426	          activeFilters.innerHTML = filters.map(function (item) {
   427	            return '<button type="button" class="jobs-active-chip" data-clear-key="' + item.key + '">' + item.label + '<i class="fa-solid fa-xmark" aria-hidden="true"></i></button>';
   428	          }).join('') + '<button type="button" class="jobs-active-chip is-clear-all" data-clear-key="all">Xóa tất cả</button>';
   429	        }
   430	
   431	        function compareCards(a, b, sortValue) {
   432	          var aFeatured = Number(a.dataset.featured || 0);
   433	          var bFeatured = Number(b.dataset.featured || 0);
   434	          var aPublish = Date.parse(a.dataset.publishDate || '') || 0;
   435	          var bPublish = Date.parse(b.dataset.publishDate || '') || 0;
   436	          var aDeadline = Date.parse(a.dataset.deadline || '') || 0;
   437	          var bDeadline = Date.parse(b.dataset.deadline || '') || 0;
   438	          var aSalary = Number(a.dataset.salaryMax || 0);
   439	          var bSalary = Number(b.dataset.salaryMax || 0);
   440	
   441	          if (sortValue === 'deadline-asc') {
   442	            return aDeadline - bDeadline || bPublish - aPublish;
   443	          }
   444	          if (sortValue === 'salary-desc') {
   445	            return bSalary - aSalary || bPublish - aPublish;
   446	          }
   447	          if (sortValue === 'featured-first') {
   448	            return bFeatured - aFeatured || bPublish - aPublish;
   449	          }
   450	          return bPublish - aPublish || aDeadline - bDeadline;
   451	        }
   452	
   453	        function applyFilters() {
   454	          var searchValue = normalizeText(searchInput ? searchInput.value : '');
   455	          var locationValue = locationSelect ? locationSelect.value : '';
   456	          var roleValue = roleSelect ? roleSelect.value : '';
   457	          var employmentValue = employmentSelect ? employmentSelect.value : '';
   458	          var workModeValue = workModeSelect ? workModeSelect.value : '';
   459	          var experienceValue = experienceSelect ? experienceSelect.value : '';
   460	          var sortValue = sortSelect ? sortSelect.value : 'publish-desc';
   461	          var visible = 0;
   462	          var visibleCards = [];
   463	
   464	          cards.forEach(function (card) {
   465	            var matchesSearch = !searchValue || (card.dataset.search || '').indexOf(searchValue) !== -1;
   466	            var matchesLocation = !locationValue || (card.dataset.locationGroup || '') === locationValue;
   467	            var matchesRole = !roleValue || (card.dataset.roleGroup || '') === roleValue;
   468	            var matchesEmployment = !employmentValue || (card.dataset.employment || '') === employmentValue;
