   472	            var show = matchesSearch && matchesLocation && matchesRole && matchesEmployment && matchesWorkMode && matchesExperience;
   473	            card.classList.toggle('is-hidden', !show);
   474	            if (show) {
   475	              visible += 1;
   476	              visibleCards.push(card);
