   498	          }
   499	          if (emptyState) {
   500	            emptyState.hidden = visible !== 0;
   501	          }
   502	          renderActiveFilters(filters);
   503	          syncQuickRoleButtons();
   504	        }
   505	
   506	        form.addEventListener('input', applyFilters);
   507	        form.addEventListener('change', applyFilters);
   508	
   509	        quickRoleButtons.forEach(function (button) {
   510	          button.addEventListener('click', function () {
