   541	            form.reset();
   542	            applyFilters();
   543	          });
   544	        }
   545	
   546	        applyFilters();
   547	      }
   548	
   549	      document.addEventListener('DOMContentLoaded', initJobsFilter);
   550	    })();
   551	  </script>
   552	""".strip()
