   881	                "location": job.meta["location"],
   882	                "locationGroupKey": job.meta["locationGroupKey"],
   883	                "locationGroupLabel": job.meta["locationGroupLabel"],
   884	                "roleGroupKey": job.meta["roleGroupKey"],
   885	                "roleGroupLabel": job.meta["roleGroupLabel"],
   886	                "salaryLabel": job.meta.get("salaryLabel") or "",
   887	                "employmentType": job.meta.get("employmentType") or "",
   888	                "employmentTypeLabel": display_employment(job.meta.get("employmentType") or ""),
   889	                "workMode": job.meta.get("workMode") or "",
   890	                "workModeLabel": display_work_mode(job.meta.get("workMode") or ""),
   891	                "experienceLevel": job.meta.get("experienceLevel") or "",
   892	                "experienceLevelLabel": display_experience(job.meta.get("experienceLevel") or ""),
   893	                "deadline": job.meta["deadline"],
   894	                "publishDate": job.meta["publishDate"],
   895	                "status": job.meta["status"],
   896	                "featured": bool(job.meta.get("featured")),
   897	                "urgent": bool(job.meta.get("urgent")),
   898	                "summary": job.meta["summary"],
   899	                "href": job.meta["href"],
   900	                "sourceSite": job.meta["sourceSite"],
   901	                "sourceUrl": job.meta["sourceUrl"],
   902	            }
   903	        )
