   907	def cleanup_stale_detail_pages(public_jobs: list[Job]) -> None:
   908	    expected = {job.detail_path.name for job in public_jobs}
   909	    if not OUTPUT_DIR.exists():
   910	        return
   911	    for path in OUTPUT_DIR.glob("*.html"):
   912	        if path.name not in expected:
   913	            path.unlink()
