   916	def update_homepage_recruitment_fallback(payload: list[dict[str, Any]]) -> None:
   917	    if not INDEX_PAGE.exists():
   918	        return
   919	    text = INDEX_PAGE.read_text(encoding="utf-8")
   920	    pattern = re.compile(
   921	        r"(<!-- HOME_RECRUITMENT_FALLBACK_START -->\s*)(.*?)(\s*<!-- HOME_RECRUITMENT_FALLBACK_END -->)",
   922	        re.S,
   923	    )
   924	    if not pattern.search(text):
   925	        return
   926	    teaser_payload = payload[:3]
   927	    replacement_json = json.dumps(teaser_payload, ensure_ascii=False, indent=2)
   928	    INDEX_PAGE.write_text(
   929	        pattern.sub(lambda match: f"{match.group(1)}{replacement_json}{match.group(3)}", text, count=1),
   930	        encoding="utf-8",
   931	    )
