   934	def main() -> None:
   935	    today = date.today()
   936	    jobs = load_jobs(today)
   937	    jobs.sort(
   938	        key=lambda item: (
   939	            0 if item.effective_status == "active" else 1,
   940	            0 if item.meta.get("featured") else 1,
   941	            -int(item.publish_date.strftime("%Y%m%d")),
   942	            int(item.deadline.strftime("%Y%m%d")),
   943	            item.meta["title"],
   944	        )
   945	    )
   946	
   947	    OUTPUT_DIR.mkdir(parents=True, exist_ok=True)
   948	    DATA_DIR.mkdir(parents=True, exist_ok=True)
   949	    FEED_DIR.mkdir(parents=True, exist_ok=True)
   950	
   951	    public_jobs = [job for job in jobs if job.effective_status not in {"draft", "closed"}]
   952	
   953	    cleanup_stale_detail_pages(public_jobs)
   954	
   955	    for job in public_jobs:
   956	        job.detail_path.write_text(render_detail_page(job), encoding="utf-8")
   957	
   958	    payload = build_json_payload(public_jobs)
   959	    DATA_FILE.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
   960	    FEED_FILE.write_text(json.dumps(payload[:10], ensure_ascii=False, indent=2), encoding="utf-8")
   961	    update_homepage_recruitment_fallback(payload)
   962	    LIST_PAGE.write_text(render_list_page(public_jobs, today), encoding="utf-8")
   963	    JOBS_SITEMAP_FILE.write_text(render_jobs_sitemap(public_jobs), encoding="utf-8")
   964	    SITEMAP_INDEX_FILE.write_text(render_sitemap_index(), encoding="utf-8")
   965	    ensure_jobs_sitemap_in_robots()
   966	
   967	    print(json.dumps(
   968	        {
